create table public.synthetic_ids(batch uuid);
select public.sanji_youtube_manual_confirm_batch('11111111-1111-4111-8111-111111111111',(select batch from public.synthetic_ids),repeat('b',64));
select public.sanji_youtube_manual_schedule_batch('11111111-1111-4111-8111-111111111111',(select batch from public.synthetic_ids),repeat('b',64),jsonb_build_array(jsonb_build_object('id','22222222-2222-4222-8222-222222222222','version',1,'email','synthetic@example.test','payloadHash',repeat('c',64),'messageId','synthetic')),(((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::timestamp+interval '10 hours') at time zone 'Asia/Seoul');
update public.sanji_youtube_manual_schedule set run_at=now()-interval '1 minute';
